#!ibl edition=2
[def:확인]($row) {
  $f = [self:forage]{op:"recall",locus:$row.path,evidence_check:"content"}
  $mine = $f.map >> [table:filter]{where:($r)=>$r.id == $row.note.id}
  $hit = len($mine) == 1 ? $mine[0] : null
  return {id:$row.id,note_id:$row.note.id,own_count:get($f,"own_count"),locus_exists:get($f,"locus_exists"),
    found:len($mine),locus_ok:($hit == null ? false : $hit.locus == $row.path),
    generalizes:($hit == null ? null : $hit.generalizes),prior_class:($hit == null ? null : $hit.prior_class),
    stored_claim:($hit == null ? null : $hit.claim),
    evidence_status:($hit == null ? null : $hit.evidence_status),provenance:($hit == null ? null : $hit.provenance),
    evidence_doc:($hit == null ? null : get($hit,"evidence_doc"))}
}
return $입력 >> [table:each]{ [fn:확인]{row:$it} }
